UPDATE `products` SET `short_description` = 'SEO-платформа для відстеження позицій сайту, аудиту та видимості бренду у відповідях ChatGPT, Gemini і Perplexity.', `full_description` = 'SE Ranking поєднує звичні SEO-інструменти з відстеженням того, як бренд показується у відповідях AI-платформ. Кожен тариф дає щоденне відстеження позицій за ключовими словами, аудит сайту, кілька проєктів і місць для менеджерів та щомісячні кредити для API. Є 14-денний безкоштовний період без банківської картки.', `main_features` = 'Щоденне відстеження позицій за ключовими словами
Аудит сайту (від 250 000 сторінок на місяць)
Відстеження видимості в AI-відповідях (ChatGPT, Gemini, Perplexity)
Кілька проєктів і місць для менеджерів
Щомісячні кредити для API' WHERE `id` = 627;
UPDATE `products` SET `short_description` = 'Платформа для оптимізації контенту під Google та AI-пошук: генерує SEO-тексти й відстежує відповіді AI-моделей на ваші запитання.', `full_description` = 'NeuronWriter допомагає оптимізувати контент і для позицій у Google, і для видимості в AI-пошуку. Вбудований генеративний AI створює SEO-орієнтовані тексти, а окремий моніторинг показує, що відповідають на ваші запитання Google, ChatGPT, Perplexity та інші моделі. Є помічник Neuro AI, налаштований на SEO, 7-денне тестування і 30-денна гарантія повернення коштів.', `main_features` = 'AI-генерація SEO-текстів
Моніторинг відповідей AI-моделей (Google, ChatGPT, Perplexity)
Помічник Neuro AI, налаштований на SEO
Аналізи контенту та окремі проєкти для сайтів' WHERE `id` = 628;
UPDATE `products` SET `short_description` = 'SEO-плагін для WordPress: підказує, як покращити тексти й налаштування сторінок для пошуку; у Premium генерує заголовки й описи за допомогою AI.', `full_description` = 'Yoast SEO працює всередині WordPress і в реальному часі підказує, що виправити в статті чи сторінці, щоб її легше знаходили в пошуку. Платна версія додає менеджер переспрямувань, інструмент внутрішніх посилань, попередній перегляд для соцмереж і необмежену AI-генерацію заголовків та мета-описів. Для інтернет-магазинів є окремий тариф WooCommerce SEO зі структурованими даними товарів.', `main_features` = 'Підказки з SEO для контенту прямо в WordPress
Аналіз контенту в реальному часі (Premium)
Менеджер переспрямувань і внутрішні посилання (Premium)
AI-генерація заголовків і мета-описів (Premium)
SEO для товарів WooCommerce (окремий тариф)' WHERE `id` = 629;
UPDATE `products` SET `short_description` = 'SEO-плагін для WordPress: перевірка сторінок, генератор schema-розмітки, відстеження позицій і безкоштовна версія.', `full_description` = 'Rank Math — SEO-плагін для WordPress: перевіряє SEO сторінок (понад 30 тестів), генерує schema-розмітку, будує XML-карти сайту й підключається до Google Search Console. У платних тарифах додаються відстеження позицій за ключовими словами та AI Link Genius, а тариф Business дає звіти з власним брендом для агенцій. Є безкоштовна версія з основними можливостями.', `main_features` = 'Понад 30 SEO-перевірок сторінок
Генератор schema-розмітки
Google Search Console та XML-карти сайту
Відстеження позицій за ключовими словами (PRO)
AI Link Genius (PRO)
Звіти з власним брендом (Business)' WHERE `id` = 630;

